/// <reference path="./manga-provider.d.ts" />

class Provider {
    private baseUrl = "https://mangafire.to";
    private apiUrl = "https://mangafire.to/api";

    getSettings(): Settings {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: true,
        };
    }

    private async getJson(url: string): Promise<any> {
        const response = await fetch(url, {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "Referer": this.baseUrl + "/",
            },
        });

        if (!response.ok) {
            throw new Error("MangaFire HTTP " + response.status);
        }

        return await response.json();
    }

    private getMangaId(item: any): string {
        if (item.id !== undefined && item.id !== null) {
            return String(item.id);
        }

        const url = String(item.url || "");
        const match = url.match(/\/title\/([^\/-]+)(?:-|$)/);

        if (match) {
            return match[1];
        }

        const legacy = url.match(/\/manga\/[^\/.]+\.([^\/]+)$/);
        if (legacy) {
            return legacy[1];
        }

        return url.split("/").pop() || "";
    }

    private getMangaUrl(item: any, id: string): string {
        if (item.url) {
            return String(item.url).startsWith("http")
                ? String(item.url)
                : this.baseUrl + String(item.url);
        }

        return this.baseUrl + "/title/" + id;
    }

    async search(opts: QueryOptions): Promise<SearchResult[]> {
        const url =
            this.apiUrl +
            "/titles?keyword=" +
            encodeURIComponent(opts.query) +
            "&language=en&limit=30&page=1";

        const json = await this.getJson(url);
        const items = Array.isArray(json.items) ? json.items : [];

        return items.map((item: any) => {
            const id = this.getMangaId(item);

            return {
                id: id,
                title: item.title || "",
                synonyms: Array.isArray(item.alternativeTitles)
                    ? item.alternativeTitles.map((x: any) => String(x))
                    : [],
                image: item.poster
                    ? (item.poster.medium || item.poster.large || item.poster.small)
                    : undefined,
            };
        }).filter((item: SearchResult) => item.id && item.title);
    }

    async findChapters(mangaId: string): Promise<ChapterDetails[]> {
        const results: ChapterDetails[] = [];
        const seen = new Set<string>();

        const limit = 200;
        let page = 1;
        let hasNext = true;

        while (hasNext && page <= 100) {
            const url =
                this.apiUrl +
                "/titles/" +
                encodeURIComponent(mangaId) +
                "/chapters" +
                "?language=en&sort=number&order=desc&limit=" +
                limit +
                "&page=" +
                page;

            const json = await this.getJson(url);
            const items = Array.isArray(json.items) ? json.items : [];

            for (const item of items) {
                const id = String(item.id ?? "");
                if (!id || seen.has(id)) {
                    continue;
                }

                seen.add(id);

                const number = item.number != null
                    ? String(item.number)
                    : "";

                const titleParts = [];
                if (number) {
                    titleParts.push("Ch. " + number);
                }
                if (item.name) {
                    titleParts.push(String(item.name));
                }

                results.push({
                    id: id,
                    url: this.baseUrl + "/read/" + encodeURIComponent(mangaId) +
                        "/en/chapter-" + encodeURIComponent(number),
                    title: titleParts.length ? titleParts.join(": ") : "Chapter",
                    chapter: number,
                    index: 0,
                    scanlator: item.type === "official" ? "official" : undefined,
                    language: item.language || "en",
                    updatedAt: item.createdAt
                        ? new Date(Number(item.createdAt) * 1000).toISOString()
                        : undefined,
                });
            }

            hasNext = !!(json.meta && json.meta.hasNext === true);
            page++;
        }

        // API returns descending order; Seanime expects ascending order.
        results.reverse();

        for (let i = 0; i < results.length; i++) {
            results[i].index = i;
        }

        return results;
    }

    async findChapterPages(chapterId: string): Promise<ChapterPage[]> {
        const json = await this.getJson(
            this.apiUrl + "/chapters/" + encodeURIComponent(chapterId)
        );

        const pages =
            json &&
            json.data &&
            Array.isArray(json.data.pages)
                ? json.data.pages
                : [];

        return pages.map((page: any, index: number) => ({
            url: String(page.url),
            index: index,
            headers: {
                "Referer": this.baseUrl + "/",
            },
        })).filter((page: ChapterPage) => page.url);
    }
}
